def safe_divide(a,b):
    try:
        return a /b 
    except ZeroDivisionError:
        print("❌ ZeroDivisionError: Can't divide by zero")
        return None
    except TypeError:
        print("❌ TypeError: Both inputs must be numbers")
        return None   
    except Exception as e:
        print(f"❌ Unexpected: {type(e).__name__}: {e}")
        return None

