def read_file_safe(filename):
    try:
       with open(filename,"r") as file:
            return file.read() 
    except FileNotFoundError:
        print(f"❌ file {filename} not found")
        return None
    except PermissionError:
        print(f"❌ No persmission to read {filename}")
        return None

